  VALUES 
    (486::BIGINT, 'Excelente profesor, me atrevería a decir que el mejor de la escuela de matemáticas. Explica claro se le comprende muy fácil, no dude en matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-09-04T00:00:00+00:00'::TIMESTAMPTZ, '4ab7c193fa0ea5d3ea3754587b5d928e69bb9d2a4ce3665e207eda48896c986f'::TEXT, ARRAY[605]::BIGINT[]),
