    (486::BIGINT, 'De las mejores opciones para este curso, no tenga miedo de matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-19T00:00:00+00:00'::TIMESTAMPTZ, 'a19c9f33026c3eefde7a1808d8331472ae8590ce471add0a6331efd2c9ab6e9d'::TEXT, ARRAY[1018]::BIGINT[]),
    (486::BIGINT, 'Excelente profe, explica muy bien, las clases no se hacen aburridas con el, deja algunos ejercicios para repasar, la última clase antes del examen la utiliza para repasar, los quizes son de 2 preguntas y aveces los deja de tarea. Tiene mucha disponibilidad en consulta y si se pone interés le ayuda!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2025-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'd9206c8f3d91c9256540bed2b82fb924015a93871e54f5a34efb6c44df2d6925'::TEXT, ARRAY[563]::BIGINT[]),
