    (486::BIGINT, 'El profe es demasiado bueno. Cae súper bien, le explica lo que necesite, en la clase o por Telegram. Le ayuda a uno (evalúa justo) y siempre está disponible en consulta y el curso fue como 70% virtual (incluyendo los quices).'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'de6e4d729ac39f7122afbd6e36c18db2f05daf6efc8b8329bc4e7f5c36a2464b'::TEXT, ARRAY[1049]::BIGINT[]),
    (486::BIGINT, 'Muy buen profesor en todo aspecto, respetuoso y comprensivo. Me parece que era la primera vez que daba el curso y aún así toda la materia quedó muy clara. Si busca un profesor para llevar CDI, esta es una gran opción. Muy recomendado, hace el curso que mucho más sencillo y llevadero.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'ff9978eebbc4010aef4a869b884777cca20f7db20cc5c1f2c7bf27b25f7f1d95'::TEXT, ARRAY[605]::BIGINT[]),
    (486::BIGINT, 'un gran profe se le entiende todo y se hace practica en clase para entender mejor la materia para mi el mejor profe de mate que he tendio'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'e4a6a99b7a951a6b4170ebf4f20329dcf98c2c289ecf09e3217844b93831cc1c'::TEXT, ARRAY[1018, 563]::BIGINT[]),
    (486::BIGINT, 'Poco se habla de lo infravalorado que esta el profe Jorge, es un EXCELENTE PROFESOR, explica super bien, ayuda a todos, esta a disposición de explicarte fuera de clase, es super amable y respetuoso. EXCELENTE'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-10T00:00:00+00:00'::TIMESTAMPTZ, '4d06399e17682e8cedb3c8ab2bcb23159a5001588a47237d5aee9f501e0b67f6'::TEXT, ARRAY[1018]::BIGINT[]),
    (486::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '904b97f68bf9b7c7ef2a4ad7cfe0724060cdf25d42a17d9d6b5d9d63177173be'::TEXT, ARRAY[1018]::BIGINT[]),
    (486::BIGINT, 'Es un profe muy bueno y explica muy bien, manda bastantes prácticas las cuales recomiendo hacer constantemente.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'f3baa7a75adf896cab33bf2075b632720b92a6aa101f2157a92adbd8420cfb9d'::TEXT, ARRAY[1018]::BIGINT[]),
    (486::BIGINT, 'Es un profe chill, podría dar algo más de detalle en alguna teoría, pero repite las veces que sea necesario si usted le pide. Es respetuoso, amigable, y si la clase lo pide, atrasa fechas de quices. Sepan que mate discreta es dura sin importar el profe, hay que poner horas muchas horas extras.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-17T00:00:00+00:00'::TIMESTAMPTZ, '1a7bb5842becc0e1e5ccf7783e2b488fc268081981de62ccf6304b3c9b93ae90'::TEXT, ARRAY[1018]::BIGINT[]),
    (486::BIGINT, 'Un profesor que es muy ordenado a la hora de estructurar las clases, califica bastante rápido , explica fenomenal , manda muchas prácticas lo cual es bueno para practicar y evacua todas las dudas en clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, '6c0c3d257ca79da8129e5fa997cf60be959f5ff9b86cf994b3c6c7e33e7f51e9'::TEXT, ARRAY[1018]::BIGINT[]),
    (486::BIGINT, 'Muy buen profe, explica muy bien'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-05-17T00:00:00+00:00'::TIMESTAMPTZ, '89b2c4ede25f5ec4d8b03308a93e44ba997c297c23269b83ed634e7f2c5b234e'::TEXT, ARRAY[1018]::BIGINT[]),
    (486::BIGINT, 'Es un super profesor! Si quieren llevar discreta con una buena nota y no sobrecargarse con esa materia. Él es su mejor opción'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2024-05-17T00:00:00+00:00'::TIMESTAMPTZ, '415288b4006b7ce37154eb5f8c1f02abe05e719d73bc773fa03c447d72ed3d06'::TEXT, ARRAY[1018]::BIGINT[]),
    (486::BIGINT, 'Es excelente, explica fácil, quizes fáciles, califica bien...'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'cd8986c19906d3bfbd24fe86b184331026836e096bbda2e30dd51bf9ba39066d'::TEXT, ARRAY[605]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
